INSERT OR IGNORE INTO group_messages (thread_id, message_id, zalo_user_id, display_name, text, msg_type, ts, is_self, created_at, deleted_at, deleted_source) VALUES ('1913869945242410752', '8186631457594', '9157976952623014552', 'Vũ Trọng', '@Huy à thật ra sẽ có nhiều ae trong nhóm này còn ko biết gì về AI ấy :d thím cứ viết 1 bài quy trình. Sau đó về mảng AI tạo video mình sẽ biên bài hỗ trợ theo sau để kết hợp thành Full quy trình cho ae dễ hiểu', 'webchat', 1787545781251, 0, 1787545781210, null, '');
INSERT OR IGNORE INTO group_messages (thread_id, message_id, zalo_user_id, display_name, text, msg_type, ts, is_self, created_at, deleted_at, deleted_source) VALUES ('1913869945242410752', '8186643934454', '7310089955567951357', 'Huy', 'Cái này thực ra thì nó cũng có 3 bước cơ bản thôi,chọn sp e chia sẻ ở trên rồi, các bác chụp ảnh sp hoặc tải ảnh sp về, tạo 1 ảnh sẽ làm ảnh gốc để sử dụng thay trang phục sau này,tiến hành thay trang phục hàng loạt ,chuyển ảnh đã thay trang phục trước đó thành video', 'webchat', 1787545949015, 0, 1787545949067, null, '');
INSERT OR IGNORE INTO group_messages (thread_id, message_id, zalo_user_id, display_name, text, msg_type, ts, is_self, created_at, deleted_at, deleted_source) VALUES ('1913869945242410752', '8186644647430', '7310089955567951357', 'Huy', 'Vậy thôi k có gì phức tạp cả', 'webchat', 1787545958738, 0, 1787545958791, null, '');
INSERT OR IGNORE INTO group_messages (thread_id, message_id, zalo_user_id, display_name, text, msg_type, ts, is_self, created_at, deleted_at, deleted_source) VALUES ('1913869945242410752', '8186645995573', '5325819983274797670', 'Hiệu', '@Huy phức tạp là làm gì để khán giả nhiều thôi kaka', 'webchat', 1787545977272, 0, 1787545977224, null, '');
INSERT OR IGNORE INTO group_messages (thread_id, message_id, zalo_user_id, display_name, text, msg_type, ts, is_self, created_at, deleted_at, deleted_source) VALUES ('1913869945242410752', '8186647374472', '7310089955567951357', 'Huy', '@Hiệu hoa lá hẹ là để mời học viên b-)', 'webchat', 1787545996051, 0, 1787545996035, null, '');
INSERT OR IGNORE INTO group_messages (thread_id, message_id, zalo_user_id, display_name, text, msg_type, ts, is_self, created_at, deleted_at, deleted_source) VALUES ('1913869945242410752', '8186650246596', '7310089955567951357', 'Huy', 'Còn hiện tại e thấy mảng thời trang thì gương dễ làm,chuyển đổi ổn', 'webchat', 1787546035523, 0, 1787546035491, null, '');
INSERT OR IGNORE INTO group_messages (thread_id, message_id, zalo_user_id, display_name, text, msg_type, ts, is_self, created_at, deleted_at, deleted_source) VALUES ('1913869945242410752', '8186655803799', '7310089955567951357', 'Huy', 'Về thay trang phục thì tạo cái tool thay hàng loạt dùng trực tiếp,tạo trực tiếp trong flow luôn là đủ đáp ứng làm thoải mái r', 'webchat', 1787546112317, 0, 1787546112263, null, '');
INSERT OR IGNORE INTO group_messages (thread_id, message_id, zalo_user_id, display_name, text, msg_type, ts, is_self, created_at, deleted_at, deleted_source) VALUES ('1913869945242410752', '8186658061979', '7310089955567951357', 'Huy', 'Thời trang thì dùng Omni sẽ cho kết quả hình ảnh,động tác ok hơn các model khác trong flow', 'webchat', 1787546143733, 0, 1787546143662, null, '');
INSERT OR IGNORE INTO group_messages (thread_id, message_id, zalo_user_id, display_name, text, msg_type, ts, is_self, created_at, deleted_at, deleted_source) VALUES ('1913869945242410752', '8186662459342', '1475990514309473780', 'Tu', 'Tổng hợp tut bkt cho kênh tránh bị hold:
Tut thứ 1 :  Anh em nối ga bật kiếm tiền trên google chrome tab ẩn danh nhé tránh giảm tỷ lệ hold bước 3.
Tút thứ 2 : Anh em đang dính hold bước 2, hoặc bước 3 có thể thay ga new khác vào cho duyệt lại từ đầu bật bằng tút thứ 2 > tỷ lệ bkt nhanh it bi hold.
Tut thứ 3 :duyệt trong 12h - 48h Anh em vào phần tuỳ chỉnh kênh thêm phần gới thiệu> và liên kết mạng xã hội ví dụ: tele, fb, tiktok và thêm email vào nhé . Sau đó kết hợp login ẩn danh chrome để nối ga bkt .>> Uu tiên tut thứ 3 này nha ae. Cám ơn', 'chat.photo', 1787546205323, 0, 1787546205363, null, '');
INSERT OR IGNORE INTO group_messages (thread_id, message_id, zalo_user_id, display_name, text, msg_type, ts, is_self, created_at, deleted_at, deleted_source) VALUES ('1913869945242410752', '8186662691251', '1475990514309473780', 'Tu', 'vừa chôm, nóng hổi', 'webchat', 1787546208597, 0, 1787546208519, null, '');
INSERT OR IGNORE INTO group_messages (thread_id, message_id, zalo_user_id, display_name, text, msg_type, ts, is_self, created_at, deleted_at, deleted_source) VALUES ('1913869945242410752', '8186694821147', '7946525001172739016', 'Trien Nguyen', 'Kinh nghiệm cá nhân về cách hạn chế bị khóa tài khoản Google Adsense vĩnh viễn. Anh em có thể thử.
- Hiện tại mình vẫn dùng GA mua từ bên khác, khi mua về đăng nhập bằng GPM login ( hoặc những cái tương tự) và dùng proxy dân cư Việt Nam. Sau đó nhớ đổi ngôn ngữ GA sang tiếng Việt. ( cái này hỏi chatgpt cách làm là ra.)
- Đăng nhập và ngâm khoảng 5 -7 ngày thì vào phần thêm thành viên quản trị trong GA, sau đó bạn thêm 2 email chính chủ mà bạn hay dùng nhất. Khi thêm Google sẽ bắt xác thực bằng email khác hoặc khuôn mặt qua camera điện thoại. Lúc này chọn xác thực qua camera điện thoại. Xác thực xong sẽ được thêm email quản trị khác. Mỗi lần thêm email quản trị khác sẽ cần xác thực bằng camera trên điện thoại thêm 1 lần nữa. Chọn quyền quản trị cao nhất cho từng email mới thêm. Sau đó xóa quyền quản trị của email cũ đi là được.
- Còn nhận PIN GA nhanh không bị xin nhận nhiều lần thì các bạn để số điện thoại luôn trong dòng 2 của địa chỉ là được nhé, nhận pin sau 7 ngày.', 'webchat', 1787546665638, 0, 1787546665671, null, '');
